// ─────────────────────────────────────────────────────────────────────────────
// stance-topic-vocab.mjs — scoring vocabulary for every PolitiDex issue key
// ─────────────────────────────────────────────────────────────────────────────
// The scorer (stance-score-core.mjs) keeps its hand-calibrated rules for
// cost_living (the Talarico ground truth) and healthcare_costs. Every OTHER key
// in the issue register (ISSUE_MAP in alignment-tool.js → db/issue-keys.json,
// the same 125 keys the related-issues map relates) gets its rules from the
// compact spec below. The rule engine is unchanged: R1–R6 and WEIGHTS apply to
// every topic alike; a topic only supplies what counts as a mention, an
// explicit statement and an implication.
//
// POLARITY. "support" always means support for the issue's own position — the
// register's chip line, quoted in `pos` — and "oppose" means against it. So
// "secure the border" is support on border_security, and "ban assault weapons"
// is support on gun_safety but oppose on gun_rights.
//
// SPEC FIELDS (all regex source strings, matched case-insensitively):
//   label     reader-facing issue name (register label without the emoji)
//   pos       the position "support" means (register chip line)
//   terms     what counts as a MENTION of the topic
//   up        objects of a pro verb (protect / expand / fund …) → explicit support
//   down      objects of a down verb (cut / end / ban / stop …) → explicit support
//   upCon     objects of a pro verb → explicit oppose
//   downCon   objects of a down verb → explicit oppose
//   pro, con  whole extra fragments → explicit support / oppose
//   problems  R6(a): a remedy verb aimed at one of these → implied support
//   protects  R6(a): a repeal verb aimed at one of these → implied oppose
//   outcome   R6(b): an outcome the speaker wants changed (support when repeated)
//
// A verb and its object must sit in one clause: the gap between them may not
// cross "and / but / while / or …", so "cut taxes and protect Social Security"
// never reads as cutting Social Security.

const PRO = String.raw`(?:protect\w{0,3}|defend\w{0,3}|preserv\w{0,3}|strengthen\w{0,3}|support\w{0,3}|champion\w{0,3}|fight(?:s|ing)? (?:for|to (?:protect|expand|keep|secure|fund|pass|save))|fought (?:for|to)|stand(?:s|ing)? up for|stood up for|expand\w{0,3}|invest\w{0,3} in|fully fund\w{0,3}|fund(?:s|ed|ing)?|increas\w{0,3}|boost\w{0,3}|secur(?:e|es|ed|ing)|restor\w{0,3}|sav(?:e|es|ed|ing)|keep(?:s|ing)?|guarantee\w{0,2}|improv\w{0,3}|deliver\w{0,3}|build(?:s|ing)?|built|pass(?:es|ed|ing)?|back(?:s|ed|ing)?|uphold\w{0,3}|safeguard\w{0,3}|creat(?:e|es|ed|ing)|mak(?:e|es|ing)|bring(?:s|ing)?|requir(?:e|es|ed|ing)|help\w{0,3}|honor\w{0,3}|enforc\w{0,3}|moderniz\w{0,3}|speed(?:s|ing)? up|sped up|legaliz\w{0,3}|decriminaliz\w{0,3}|rais(?:e|es|ed|ing)|unleash\w{0,3}|hold\w{0,3}|put(?:s|ting)?|giv(?:e|es|ing)|lock(?:s|ed|ing)? down|finish\w{0,3}|deport\w{0,3}|audit\w{0,3}|welcom\w{0,3}|conserv\w{0,3}|cod\w{0,3}|act(?:s|ed|ing)? on)`;

const DOWN = String.raw`(?:cut(?:s|ting)?|lower(?:s|ed|ing)?|reduc(?:e|es|ed|ing)|slash(?:es|ed|ing)?|end(?:s|ed|ing)?|stop(?:s|ped|ping)?|ban(?:s|ned|ning)?|eliminat\w{0,3}|abolish\w{0,3}|repeal\w{0,3}|block\w{0,3}|oppos(?:e|es|ed|ing)|reject\w{0,3}|fight(?:s|ing)? against|crack(?:s|ing)? down on|rein(?:s|ing)? in|cap(?:s|ped|ping)?|limit\w{0,3}|roll(?:s|ed|ing)? back|scrap(?:s|ped|ping)?|defund\w{0,3}|gut(?:s|ted|ting)?|shrink\w{0,3}|tackl\w{0,3}|combat\w{0,3}|prevent\w{0,3}|stand(?:s|ing)? against|vot(?:e|ed|ing) against|freez\w{0,3}|halt\w{0,3}|restrict\w{0,3}|rescind\w{0,3}|dismantl\w{0,3}|curb\w{0,3}|fix(?:es|ed|ing)?|bring(?:s|ing)? down)`;

// R6(a) remedy verbs (problem + remedy) and repeal verbs (removing a protection).
const REMEDY = String.raw`(?:lower(?:s|ed|ing)?|cut(?:s|ting)?|reduc(?:e|es|ed|ing)|slash(?:es|ed|ing)?|stop(?:s|ped|ping)?|end(?:s|ed|ing)?|ban(?:s|ned|ning)?|crack(?:s|ing)? down on|rein(?:s|ing)? in|tackl\w{0,3}|fix(?:es|ed|ing)?|combat\w{0,3}|fight(?:s|ing)?|fought|confront\w{0,3}|address\w{0,3}|solv\w{0,3}|prevent\w{0,3}|root(?:s|ed|ing)? out|clean(?:s|ed|ing)? up|go after|hold \w+ accountable for|curb\w{0,3}|bring(?:s|ing)? down|drive down|shut(?:s|ting)? down|dismantl\w{0,3}|eliminat\w{0,3}|halt\w{0,3}|freez\w{0,3}|cap(?:s|ped|ping)?)`;
const REPEAL = String.raw`(?:repeal\w{0,3}|scrap(?:s|ped|ping)?|kill(?:s|ed|ing)?|block\w{0,3}|eliminat\w{0,3}|gut(?:s|ted|ting)?|defund\w{0,3}|dismantl\w{0,3}|abolish\w{0,3}|rescind\w{0,3}|overturn\w{0,3}|strip(?:s|ped|ping)? away|tear(?:s|ing)? down|undermin\w{0,3})`;

// The verb→object gap stays inside one clause.
const GAP = String.raw`(?:(?!\b(?:and|but|while|or|so|because|yet|then|instead)\b)[^.!?;:]){0,60}?`;

const COST_OUTCOME = String.raw`(?:too (?:high|expensive|much)|so expensive|sky-?high|skyrocket\w*|soar(?:ing|ed)|through the roof|out of reach|unaffordable|can(?:no|'|’)?t afford|cannot afford|struggl\w* to (?:pay|afford)|priced out|crushing)`;

const alt = (xs) => (xs && xs.length ? `(?:${xs.join("|")})` : null);
const act = (verbs, objs) => (objs && objs.length ? String.raw`\b${verbs}\b${GAP}\b${alt(objs)}` : null);

